const q=s=>document.querySelector(s), paymentForm=q('#payment-form');
let financeUser,financeStudents=[],selectedStudent=null,financeOffset=0,financeBusy=false,loadVersion=0,financeZone='Europe/Moscow';
// Keep the same request ID after a lost response, even across reloads. This is
// only a retry marker; authoritative payment records live in the server database.
let paymentDraft=null,currentRate=0;
function syncPaymentMode(calculate=false){const isPackage=paymentForm.elements.payment_mode.value==='package';q('#package-count').hidden=!isPackage;q('#package-help').hidden=!isPackage;paymentForm.elements.lesson_count.required=isPackage;paymentForm.elements.lesson_count.disabled=!isPackage||financeBusy;if(calculate&&isPackage&&currentRate>0&&paymentForm.elements.lesson_count.value){const count=Number(paymentForm.elements.lesson_count.value);if(Number.isInteger(count)&&count>0)paymentForm.elements.amount.value=(count*currentRate/100).toFixed(2)}}
paymentForm.elements.payment_mode.onchange=()=>syncPaymentMode(true);paymentForm.elements.lesson_count.oninput=()=>syncPaymentMode(true);

const money=n=>(n/100).toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2})+' ₽';
async function financeApi(path,options={}){const response=await fetch('/api/'+path,{cache:'no-store',...options});const data=await response.json();if(!response.ok)throw Error(typeof data.detail==='string'?data.detail:'Не удалось выполнить запрос. Проверьте данные и подключение.');return data}
function write(path,data){return financeApi(path,{method:'POST',headers:{'Content-Type':'application/json','X-Requested-With':'KrugPi'},body:JSON.stringify(data)})}
function cell(row,value,className){const td=document.createElement('td');td.textContent=value;if(className)td.className=className;row.append(td);return td}
function freeze(value){financeBusy=value;q('#student-select').disabled=value;q('#refresh').disabled=value;paymentForm.querySelectorAll('input,select,button').forEach(e=>e.disabled=value);syncPaymentMode();document.querySelectorAll('[data-void]').forEach(b=>b.disabled=value)}
async function loadFinance(){const version=++loadVersion;if(!selectedStudent){q('#student-content').hidden=true;return}const data=await financeApi('finance/balance?'+new URLSearchParams({student_id:selectedStudent,limit:20,offset:financeOffset}));if(version!==loadVersion)return;
const s=data.student;currentRate=s.current_price_kopecks;q('#student-content').hidden=false;q('#student-name').textContent=s.name+(s.is_active?'':' · В архиве');q('#lesson-balance').textContent=s.available_lessons??'—';q('#money-balance').textContent=money(s.balance_kopecks);q('#completed').textContent=s.completed_lessons;q('#debt').hidden=s.debt_kopecks===0;q('#debt').textContent='Задолженность: '+money(s.debt_kopecks)+'. Уточните оплату у преподавателя.';q('#balance-estimate').textContent=currentRate>0?'Оценка при текущей цене '+money(currentRate)+' за урок. Остаток после полных уроков: '+money(s.remainder_kopecks)+'. Цена уже назначенных занятий может отличаться.':'Текущая цена урока не задана или равна нулю. Для оценки количества уроков укажите положительную цену в профиле ученика.';
q('#history').replaceChildren();q('#empty').hidden=!!data.items.length;q('#history-count').textContent='Всего операций: '+data.total;q('#previous').disabled=financeOffset===0;q('#next').disabled=financeOffset+20>=data.total;
for(const item of data.items){const tr=document.createElement('tr');if(item.voided_at)tr.className='voided';cell(tr,new Date(item.occurred_at*1000).toLocaleString('ru-RU',{timeZone:financeZone,dateStyle:'short',timeStyle:'short'}),'numeric');cell(tr,item.kind==='lesson'?'Проведённый урок':item.voided_at?'Оплата отменена':'Оплата');cell(tr,item.kind==='lesson'?'1 · проведён':item.lesson_count==null?'—':item.lesson_count+' · пакет','numeric');cell(tr,(item.amount_kopecks>0?'+':'')+money(item.amount_kopecks),'numeric');cell(tr,item.note+(item.voided_at?' · Причина отмены: '+item.void_reason:''));if(financeUser.role==='admin'){const actions=cell(tr,'');if(item.kind==='payment'&&!item.voided_at){const b=document.createElement('button');b.textContent='Отменить запись';b.type='button';b.dataset.void=String(item.id);b.disabled=financeBusy;b.onclick=()=>voidPayment(item);actions.append(b)}}q('#history').append(tr)}
}
function reportLoad(){q('#student-content').hidden=true;q('#status').textContent='Загружаем…';return loadFinance().then(()=>{q('#status').textContent=''}).catch(e=>{q('#status').textContent=e.message})}
q('#refresh').onclick=()=>reportLoad();
q('#student-select').onchange=()=>{selectedStudent=Number(q('#student-select').value);const url=new URL(window.location.href);url.searchParams.set('student_id',selectedStudent);history.replaceState(null,'',url);financeOffset=0;paymentForm.reset();syncPaymentMode();paymentDraft=null;q('#payment-status').textContent='';void reportLoad()};
q('#previous').onclick=()=>{financeOffset=Math.max(0,financeOffset-20);void reportLoad()};q('#next').onclick=()=>{financeOffset+=20;void reportLoad()};
paymentForm.onsubmit=async event=>{event.preventDefault();if(financeBusy)return;const price=paymentForm.elements.amount.value.trim().replace(',','.');if(!/^\d+(\.\d{1,2})?$/.test(price)){q('#payment-status').textContent='Укажите сумму в рублях с точностью до копеек.';return}const [rub,kop='']=price.split('.');const payload={student_id:selectedStudent,amount_kopecks:Number(rub)*100+Number(kop.padEnd(2,'0')),lesson_count:paymentForm.elements.payment_mode.value==='package'?Number(paymentForm.elements.lesson_count.value):null,note:paymentForm.elements.note.value.trim()};if(!Number.isSafeInteger(payload.amount_kopecks)||payload.amount_kopecks<1){q('#payment-status').textContent='Сумма должна быть больше нуля.';return}
const signature=JSON.stringify(payload),key='krug-pi-payment-retry:'+financeUser.id;try{const saved=JSON.parse(sessionStorage.getItem(key)||'null');if(saved?.signature===signature)paymentDraft=saved}catch{}if(paymentDraft?.signature!==signature)paymentDraft={signature,id:crypto.randomUUID()};try{sessionStorage.setItem(key,JSON.stringify(paymentDraft))}catch{}
freeze(true);q('#payment-status').textContent='Сохраняем…';try{await write('finance/payments',{...payload,request_id:paymentDraft.id});paymentDraft=null;try{sessionStorage.removeItem(key)}catch{}paymentForm.reset();syncPaymentMode();financeOffset=0;q('#payment-status').textContent='Оплата зачислена.';try{await loadFinance()}catch{q('#status').textContent='Оплата сохранена. Не удалось обновить баланс — нажмите «Обновить».'}}catch(e){q('#payment-status').textContent=e.message}finally{freeze(false)}};
async function voidPayment(item){if(financeBusy)return;const reason=prompt('Причина отмены ошибочной записи оплаты (деньги ученику автоматически не возвращаются):');if(!reason?.trim())return;freeze(true);try{await write('finance/payments/'+item.id+'/void',{reason:reason.trim()});q('#status').textContent='Запись оплаты отменена.';try{await loadFinance()}catch{q('#status').textContent='Запись отменена. Нажмите «Обновить», чтобы увидеть баланс.'}}catch(e){q('#status').textContent=e.message}finally{freeze(false)}}
(async()=>{try{financeUser=await financeApi('auth/me');if(financeUser.must_change_password){q('#status').textContent='Сначала смените временный пароль в личном кабинете.';return}const settings=await financeApi('lessons/settings');financeZone=settings.timezone;q('#zone').textContent='Время операций: '+financeZone;if(financeUser.role==='admin'){document.querySelector('h1').textContent='Оплаты и отчёты';document.title='Оплаты и отчёты — Круг Пи';q('#back').href='admin.html?section=students';q('#student-picker').hidden=false;q('#action-heading').hidden=false;let start=0,total;do{const page=await financeApi('admin/students?limit=100&offset='+start);financeStudents.push(...page.items);total=page.total;start+=100}while(start<total);for(const s of financeStudents){const option=document.createElement('option');option.value=s.id;option.textContent=s.name+' ('+s.username+')'+(s.is_active?'':' · В архиве');q('#student-select').append(option)}const requested=new URLSearchParams(window.location.search).get('student_id');if(requested!==null){if(!/^[1-9][0-9]*$/.test(requested)||!financeStudents.some(s=>s.id===Number(requested))){q('#status').textContent='Ученик из ссылки не найден. Вернитесь к списку учеников.';return}selectedStudent=Number(requested)}else selectedStudent=financeStudents[0]?.id||null;q('#student-select').value=String(selectedStudent??'');q('#payment-editor').hidden=false}else selectedStudent=financeUser.id;q('#content').hidden=false;if(!selectedStudent){q('#status').textContent='Сначала добавьте ученика в кабинете администратора.';return}await reportLoad()}catch(e){q('#status').textContent=e.message}})();
